#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/crypto.h>

extern void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                           const unsigned int key[8], const unsigned int counter[4]);

typedef struct {
    unsigned char *out;
    const unsigned char *in;
    size_t len;
    unsigned int key[8];
    unsigned int counter[4];
} job;

void *worker(void *arg) {
    job *j = (job*)arg;
    ChaCha20_ctr32(j->out, j->in, j->len, j->key, j->counter);
    return NULL;
}

double now() {
    struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec/1e9;
}

int main(int argc, char **argv) {
    int nthreads = argc > 1 ? atoi(argv[1]) : 1;
    size_t len = 40960000;
    unsigned char *in = malloc(len);
    unsigned char *out = malloc(len);
    memset(in, 0x41, len);
    unsigned int key[8] = {0};
    unsigned int counter[4] = {1,0,0,0};
    pthread_t *ths = malloc(sizeof(pthread_t)*nthreads);
    job *jobs = malloc(sizeof(job)*nthreads);
    size_t chunk = (len + nthreads - 1) / nthreads;
    // warmup
    for (int i=0;i<nthreads;i++){ jobs[i].out=out+i*chunk; jobs[i].in=in+i*chunk; jobs[i].len=chunk; memcpy(jobs[i].key,key,32); jobs[i].counter[0]=1+(i*chunk)/64; jobs[i].counter[1]=counter[1]; jobs[i].counter[2]=counter[2]; jobs[i].counter[3]=counter[3]; }
    double t0 = now();
    int iters = 20;
    for (int it=0; it<iters; it++) {
        for (int i=0;i<nthreads;i++) pthread_create(&ths[i], NULL, worker, &jobs[i]);
        for (int i=0;i<nthreads;i++) pthread_join(ths[i], NULL);
    }
    double t1 = now();
    double dt = (t1-t0)/iters;
    printf("nthreads=%d  %.3f ms  %.2f GB/s\n", nthreads, dt*1000, len/dt/1e9);
    return 0;
}
EOF
