#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <immintrin.h>

double now(){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec+t.tv_nsec/1e9;}

size_t N = 40960000;
unsigned char *a, *b;
int nthreads;

void* worker(void* arg){
    long id = (long)arg;
    size_t chunk = N / nthreads;
    size_t off = id * chunk;
    size_t nn = chunk / 32;
    __m256i *la = (__m256i*)(a + off);
    __m256i *lb = (__m256i*)(b + off);
    __m256i x = _mm256_set1_epi64x(0x5555555555555555ULL);
    for(size_t j=0;j<nn;j++) lb[j] = _mm256_xor_si256(la[j], x);
    return NULL;
}

int main(int argc, char**argv){
    nthreads = argc>1?atoi(argv[1]):1;
    a = malloc(N); b = malloc(N);
    memset(a, 1, N);
    pthread_t ths[64];
    // warmup
    for(int i=0;i<nthreads;i++) pthread_create(&ths[i],NULL,worker,(void*)(long)i);
    for(int i=0;i<nthreads;i++) pthread_join(ths[i],NULL);
    double t0=now();
    int iters=50;
    for(int it=0;it<iters;it++){
        for(int i=0;i<nthreads;i++) pthread_create(&ths[i],NULL,worker,(void*)(long)i);
        for(int i=0;i<nthreads;i++) pthread_join(ths[i],NULL);
    }
    double t1=now();
    double dt=(t1-t0)/iters;
    printf("nthreads=%d  %.3f ms  %.2f GB/s (r+w, 80MB traffic)\n", nthreads, dt*1000, 2.0*N/dt/1e9);
    return 0;
}
